      "detailUr": "ہندوستان کے ساتویں صدر اور یہ اعلیٰ ترین منصب سنبھالنے والے پہلے سکھ صدر؛ پنجاب کے سابق وزیر اعلیٰ اور مرکزی وزیر داخلہ۔",
